Here are modern MSTest data-driven tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: best for simple inline values ---

    [TestMethod]
    [DataRow(1, 9.99, 9.99, DisplayName = "Single item")]
    [DataRow(5, 10.00, 50.00, DisplayName = "Multiple items")]
    [DataRow(0, 25.00, 0.00, DisplayName = "Zero quantity")]
    [DataRow(1, 0.00, 0.00, DisplayName = "Zero price")]
    [DataRow(100, 1.50, 150.00, DisplayName = "Large quantity")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples: best for complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(DiscountData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (99.99m, 50, 49.995m),
    ];

    // --- DynamicData with TestDataRow for named cases ---

    [TestMethod]
    [DynamicData(nameof(EdgeCaseDiscountData))]
    public void ApplyDiscount_EdgeCases_ThrowsArgumentException(
        decimal price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static IEnumerable<TestDataRow<(decimal price, int discountPercent)>> EdgeCaseDiscountData =>
    [
        new((-10m, 10)) { DisplayName = "Negative price" },
        new((100m, -5)) { DisplayName = "Negative discount" },
        new((100m, 101)) { DisplayName = "Discount over 100%" },
    ];
}
```

**Key practices shown:**

- **`sealed` test class** — performance + design clarity
- **`DataRow`** — simple inline values with `DisplayName` for readable output
- **`DynamicData` with ValueTuples** — type-safe, supports `decimal` literals (which `DataRow` can't)
- **`TestDataRow<T>`** — adds `DisplayName` metadata to DynamicData cases
- **`Assert.ThrowsExactly<T>`** — modern exception testing (not `[ExpectedException]`)
- **Constructor init** — enables `readonly` fields
- **AAA pattern** with `MethodName_Scenario_ExpectedBehavior` naming

> **Note:** `DataRow` doesn't support `decimal` directly (it requires compile-time constants). Use `double` and cast, or prefer `DynamicData` with ValueTuples for decimal-heavy scenarios.
